INSERT INTO labs.lab_templates (slug, title, category, difficulty, runtime, brief_md, objectives, hints,
                                solution_md, ttl_minutes, simulation, status)
SELECT l->>'slug', l->>'title', l->>'category', (l->>'difficulty')::platform.difficulty, 'simulation',
       l->>'briefMd', ARRAY(SELECT jsonb_array_elements_text(l->'objectives')), l->'hints',
       l->>'solutionMd', (l->>'ttlMinutes')::int, l->'simulation', 'published'
  FROM (VALUES
    ($json${"slug":"linux-disque-plein-nginx","title":"Le site ne répond plus : disque plein","category":"linux","difficulty":"beginner","ttlMinutes":60,"briefMd":"Le site vitrine hébergé sur **web01** ne répond plus depuis ce matin. L'équipe a déjà tenté\nde relancer nginx, sans succès.\n\nVous êtes connecté en root sur la machine. Trouvez la cause, corrigez-la **sans perdre les\njournaux système** dont l'équipe sécurité a besoin, et remettez le site en ligne.\n\n> Machine simulée : tapez `help` pour voir les commandes disponibles.","objectives":["Lire l’état et le journal d’un service avec systemctl et journalctl","Relier une erreur « No space left on device » à un système de fichiers plein","Trouver ce qui occupe l’espace avec du, et libérer la place sans effacer à l’aveugle"],"hints":[{"text":"Commencez par demander à systemd pourquoi nginx est arrêté : systemctl status nginx."},{"text":"Le journal parle de « No space left on device ». Quel système de fichiers porte /var/log/nginx ? Regardez df -h."},{"text":"Cherchez ce qui remplit /var/log : du -sh /var/log/* (puis descendez dans le dossier le plus gros)."},{"text":"Videz le journal de débogage oublié avec truncate -s 0 plutôt que d’effacer /var/log, puis relancez nginx."}],"solutionMd":"**Cause** : un journal de débogage de l'application (`/var/log/app/debug.log`, 1,9 Go)\na rempli la partition `/var`. nginx doit écrire dans `/var/log/nginx` en démarrant : il échoue avec\n`No space left on device`.\n\n**Démarche** : `systemctl status nginx` → l'erreur d'écriture ; `df -h` → `/var` à 100 % ;\n`du -sh /var/log/*` → `app` occupe presque tout ; `truncate -s 0 /var/log/app/debug.log` libère la place\nsans casser le processus qui écrit encore dans ce fichier ; `systemctl restart nginx`.\n\n**Pourquoi pas `rm -rf /var/log/*`** : vous perdriez les journaux système (`syslog`, `auth.log`),\nindispensables pour comprendre un incident ou une intrusion. Et un fichier supprimé mais encore\nouvert par un processus continue d'occuper le disque tant que le processus vit.\n\n**Pour que ça ne revienne pas** : désactiver le mode débogage en production et confier\n`/var/log/app` à logrotate (rotation, compression, nombre de fichiers gardés).","simulation":{"machine":{"hostname":"web01","cwd":"/root","clock":"2026-11-24T09:12:00.000Z","nextPid":1312,"dirs":["/etc","/etc/nginx","/etc/nginx/sites-enabled","/home","/root","/tmp","/usr","/var","/var/log","/var/log/nginx","/var/lib","/var/www","/var/www/html","/var/log/app"],"files":{"/etc/nginx/nginx.conf":{"size":204,"content":"user www-data;\nworker_processes auto;\nevents { worker_connections 768; }\nhttp {\n    access_log /var/log/nginx/access.log;\n    error_log /var/log/nginx/error.log;\n    include /etc/nginx/sites-enabled/*;\n}\n"},"/etc/nginx/sites-enabled/default":{"size":87,"content":"server {\n    listen 80 default_server;\n    root /var/www/html;\n    index index.html;\n}\n"},"/var/www/html/index.html":{"size":612,"content":"<h1>Bienvenue sur web01</h1>\n"},"/var/log/syslog":{"size":39845888,"content":"Nov 24 08:58:02 web01 kernel: Linux version 6.1.0-27-amd64\nNov 24 08:58:05 web01 systemd[1]: Reached target multi-user.target.\nNov 24 08:59:10 web01 CRON[612]: (root) CMD (command -v debian-sa1 > /dev/null && debian-sa1 1 1)\n"},"/var/log/auth.log":{"size":6291456,"content":"Nov 24 09:01:44 web01 sshd[702]: Accepted publickey for root from 10.0.0.12 port 51122 ssh2\n"},"/var/log/nginx/access.log":{"size":22020096,"content":"10.0.0.40 - - [24/Nov/2026:08:59:58 +0000] \"GET / HTTP/1.1\" 200 612\n"},"/var/log/nginx/error.log":{"size":2048,"content":"2026/11/24 09:00:03 [crit] 734#734: *1 write() to \"/var/log/nginx/access.log\" failed (28: No space left on device)\n"},"/var/log/app/debug.log":{"size":2040109466,"content":"2026-11-24 09:11:59.998 DEBUG cache: miss key=session:7f3a\n2026-11-24 09:11:59.999 DEBUG cache: miss key=session:7f3b\n"}},"mounts":[{"target":"/","device":"/dev/sda1","sizeBytes":21474836480,"baseUsedBytes":6657199309},{"target":"/var","device":"/dev/sda2","sizeBytes":2147483648,"baseUsedBytes":31457280}],"services":{"nginx":{"description":"A high performance web server and a reverse proxy server","active":"failed","enabled":true,"process":"nginx","ports":[80],"writes":"/var/log/nginx/access.log","needsFiles":["/etc/nginx/nginx.conf"],"journal":["nov. 24 09:00:03 web01 systemd[1]: nginx.service: Main process exited, code=exited, status=1/FAILURE","nov. 24 09:05:41 web01 systemd[1]: Starting nginx.service - A high performance web server and a reverse proxy server...","nov. 24 09:05:41 web01 nginx[1288]: nginx: [emerg] write() to \"/var/log/nginx/access.log\" failed (28: No space left on device)","nov. 24 09:05:41 web01 systemd[1]: nginx.service: Failed with result 'exit-code'.","nov. 24 09:05:41 web01 systemd[1]: Failed to start nginx.service - A high performance web server and a reverse proxy server."]},"ssh":{"description":"OpenBSD Secure Shell server","active":"active","enabled":true,"process":"sshd","pid":702,"ports":[22],"journal":["nov. 24 08:58:04 web01 systemd[1]: Started ssh.service - OpenBSD Secure Shell server."]}}},"validators":[{"description":"nginx est démarré","check":{"kind":"service_active","service":"nginx"}},{"description":"La partition /var est sous 90 % d’occupation","check":{"kind":"disk_usage_below","mount":"/var","percent":90}},{"description":"Les journaux système sont conservés (/var/log/syslog)","check":{"kind":"path_exists","path":"/var/log/syslog","expected":true}},{"description":"Le journal d’authentification est conservé (/var/log/auth.log)","check":{"kind":"path_exists","path":"/var/log/auth.log","expected":true}}],"walkthrough":["systemctl status nginx","df -h","du -sh /var/log/*","truncate -s 0 /var/log/app/debug.log","systemctl restart nginx"]}}$json$::jsonb),
    ($json${"slug":"linux-port-80-occupe","title":"nginx refuse de démarrer : port 80 déjà pris","category":"linux","difficulty":"intermediate","ttlMinutes":60,"briefMd":"Après une mise à jour faite hier soir par un stagiaire, **web01** affiche une page\n« Apache2 Debian Default Page » au lieu du site. nginx, qui doit servir le site, est arrêté.\n\nRemettez nginx en service, et faites en sorte que le problème **ne revienne pas au prochain\nredémarrage** de la machine.\n\n> Machine simulée : tapez `help` pour voir les commandes disponibles.","objectives":["Interpréter « Address already in use » dans un journal","Trouver quel processus écoute un port avec ss -tlnp","Distinguer arrêter un service (stop) et l’empêcher de redémarrer au boot (disable)"],"hints":[{"text":"Que dit le journal de nginx au dernier démarrage ? journalctl -u nginx -n 20."},{"text":"« Address already in use » : un autre programme écoute déjà le port 80. ss -tlnp vous dit lequel."},{"text":"Arrêter apache2 libère le port maintenant ; pensez aussi à ce qui se passera au prochain démarrage (systemctl disable)."}],"solutionMd":"**Cause** : le paquet `apache2` a été installé (dépendance d'un autre paquet) ; son service\ndémarre automatiquement et écoute le port 80. nginx, lancé ensuite, ne peut plus s'y attacher :\n`bind() to 0.0.0.0:80 failed (98: Address already in use)`.\n\n**Démarche** : `journalctl -u nginx` → l'erreur de bind ; `ss -tlnp` → `apache2` sur :80 ;\n`systemctl stop apache2` libère le port ; `systemctl disable apache2` empêche son retour au boot ;\n`systemctl start nginx`.\n\n**À retenir** : `stop` agit maintenant, `disable` agit au prochain démarrage. Il faut souvent les deux\n(ou `systemctl disable --now`). Si apache2 n'a rien à faire là, le désinstaller est encore plus propre.","simulation":{"machine":{"hostname":"web01","cwd":"/root","clock":"2026-11-24T09:12:00.000Z","nextPid":1402,"dirs":["/etc","/etc/nginx","/etc/nginx/sites-enabled","/home","/root","/tmp","/usr","/var","/var/log","/var/log/nginx","/var/lib","/var/www","/var/www/html","/etc/apache2","/var/log/apache2"],"files":{"/etc/nginx/nginx.conf":{"size":204,"content":"user www-data;\nworker_processes auto;\nevents { worker_connections 768; }\nhttp {\n    access_log /var/log/nginx/access.log;\n    error_log /var/log/nginx/error.log;\n    include /etc/nginx/sites-enabled/*;\n}\n"},"/etc/nginx/sites-enabled/default":{"size":87,"content":"server {\n    listen 80 default_server;\n    root /var/www/html;\n    index index.html;\n}\n"},"/etc/apache2/ports.conf":{"size":10,"content":"Listen 80\n"},"/var/www/html/index.html":{"size":10918,"content":"<title>Apache2 Debian Default Page: It works</title>\n"},"/var/log/syslog":{"size":12582912,"content":"Nov 24 08:58:02 web01 kernel: Linux version 6.1.0-27-amd64\nNov 24 08:58:05 web01 systemd[1]: Reached target multi-user.target.\nNov 24 08:59:10 web01 CRON[612]: (root) CMD (command -v debian-sa1 > /dev/null && debian-sa1 1 1)\n"},"/var/log/auth.log":{"size":2097152,"content":""},"/var/log/apache2/access.log":{"size":4096,"content":"10.0.0.40 - - [24/Nov/2026:09:01:12 +0000] \"GET / HTTP/1.1\" 200 10918\n"},"/var/log/nginx/error.log":{"size":512,"content":"2026/11/24 08:58:06 [emerg] 655#655: bind() to 0.0.0.0:80 failed (98: Address already in use)\n"}},"mounts":[{"target":"/","device":"/dev/sda1","sizeBytes":21474836480,"baseUsedBytes":6871947674}],"services":{"nginx":{"description":"A high performance web server and a reverse proxy server","active":"failed","enabled":true,"process":"nginx","ports":[80],"writes":"/var/log/nginx/access.log","needsFiles":["/etc/nginx/nginx.conf"],"journal":["nov. 24 08:58:06 web01 systemd[1]: Starting nginx.service - A high performance web server and a reverse proxy server...","nov. 24 08:58:06 web01 nginx[655]: nginx: [emerg] bind() to 0.0.0.0:80 failed (98: Address already in use)","nov. 24 08:58:06 web01 nginx[655]: nginx: [emerg] still could not bind()","nov. 24 08:58:06 web01 systemd[1]: nginx.service: Failed with result 'exit-code'.","nov. 24 08:58:06 web01 systemd[1]: Failed to start nginx.service - A high performance web server and a reverse proxy server."]},"apache2":{"description":"The Apache HTTP Server","active":"active","enabled":true,"process":"apache2","pid":611,"ports":[80],"journal":["nov. 24 08:58:05 web01 systemd[1]: Started apache2.service - The Apache HTTP Server."]},"ssh":{"description":"OpenBSD Secure Shell server","active":"active","enabled":true,"process":"sshd","pid":702,"ports":[22],"journal":["nov. 24 08:58:04 web01 systemd[1]: Started ssh.service - OpenBSD Secure Shell server."]}}},"validators":[{"description":"nginx est démarré","check":{"kind":"service_active","service":"nginx"}},{"description":"nginx redémarrera avec la machine","check":{"kind":"service_enabled","service":"nginx","expected":true}},{"description":"apache2 ne redémarrera pas avec la machine","check":{"kind":"service_enabled","service":"apache2","expected":false}}],"walkthrough":["journalctl -u nginx -n 20","ss -tlnp | grep :80","systemctl stop apache2","systemctl disable apache2","systemctl start nginx"]}}$json$::jsonb),
    ($json${"slug":"reseau-dns-interne","title":"Plus aucun nom ne se résout après la migration DNS","category":"network","difficulty":"beginner","ttlMinutes":45,"briefMd":"Depuis ce matin, **app02** ne parvient plus à télécharger ses mises à jour depuis le dépôt interne\n`depot.exemple.fr` : « Could not resolve host ». Pourtant, l'équipe réseau affirme que le réseau fonctionne.\n\nTrouvez pourquoi les noms ne se résolvent plus, corrigez la configuration, et vérifiez que le dépôt répond.\n\n> Machine simulée : tapez `help` pour voir les commandes disponibles. Un ticket de l'équipe réseau est dans `/root`.","objectives":["Séparer un problème de résolution de noms d’un problème de connectivité","Lire /etc/resolv.conf et interroger un serveur DNS précis avec dig @serveur","Comprendre pourquoi un DNS public ne connaît pas les noms internes"],"hints":[{"text":"Le réseau marche-t-il ? Essayez ping vers une adresse IP (la passerelle 10.0.0.1), sans nom."},{"text":"Quel serveur DNS la machine interroge-t-elle ? cat /etc/resolv.conf, puis dig depot.exemple.fr."},{"text":"Le ticket dans /root donne le nouveau serveur. Testez-le d’abord : dig @10.0.0.2 depot.exemple.fr."},{"text":"Remplacez le serveur dans /etc/resolv.conf : echo 'nameserver 10.0.0.2' > /etc/resolv.conf."}],"solutionMd":"**Cause** : `/etc/resolv.conf` pointe encore vers l'ancien serveur DNS `10.0.0.53`, arrêté\nlors de la migration. Chaque résolution attend sa réponse en vain : « Temporary failure in name resolution ».\n\n**Démarche** : `ping 10.0.0.1` répond → le réseau va bien, c'est la **résolution** qui échoue ;\n`cat /etc/resolv.conf` → `nameserver 10.0.0.53` ; `dig depot.exemple.fr` → « no servers could be reached » ;\nle ticket donne le nouveau serveur ; `dig @10.0.0.2 depot.exemple.fr` le valide **avant** de modifier quoi que ce soit ;\npuis `echo 'nameserver 10.0.0.2' > /etc/resolv.conf`.\n\n**Pourquoi pas 1.1.1.1** : un DNS public résout `deb.debian.org` mais ignore tout de `depot.exemple.fr`,\nqui n'existe que dans la zone interne. Le symptôme changerait (NXDOMAIN au lieu d'un délai), sans être réglé.\n\n**Pour que ça ne revienne pas** : sur une machine gérée par DHCP, netplan ou systemd-resolved, `/etc/resolv.conf`\nest régénéré. La correction durable se fait dans la source (bail DHCP, fichier netplan, `resolvectl`).","simulation":{"machine":{"hostname":"app02","cwd":"/root","clock":"2026-11-24T10:20:00.000Z","nextPid":2100,"dirs":["/etc","/etc/network","/home","/root","/tmp","/usr","/var","/var/log"],"files":{"/etc/hosts":{"size":60,"content":"127.0.0.1\tlocalhost\n127.0.1.1\tapp02\n"},"/var/log/syslog":{"size":4194304,"content":"Nov 24 08:58:02 app02 kernel: Linux version 6.1.0-27-amd64\nNov 24 08:58:05 app02 systemd[1]: Reached target multi-user.target.\nNov 24 08:59:10 app02 CRON[612]: (root) CMD (command -v debian-sa1 > /dev/null && debian-sa1 1 1)\n"},"/etc/resolv.conf":{"size":52,"content":"# Généré lors de l'installation\nnameserver 10.0.0.53\n"},"/etc/network/interfaces":{"size":90,"content":"auto eth0\niface eth0 inet static\n    address 10.0.0.15/24\n    gateway 10.0.0.1\n"},"/root/ticket-1287.txt":{"size":260,"content":"Ticket 1287 — Migration DNS (équipe réseau)\nL'ancien serveur DNS 10.0.0.53 est arrêté depuis le 20/11.\nLe serveur DNS interne est désormais 10.0.0.2 : il résout les noms internes (*.exemple.fr) et publics.\n"}},"mounts":[{"target":"/","device":"/dev/sda1","sizeBytes":21474836480,"baseUsedBytes":4402341478}],"services":{"ssh":{"description":"OpenBSD Secure Shell server","active":"active","enabled":true,"process":"sshd","pid":702,"ports":[22],"journal":["nov. 24 08:58:04 app02 systemd[1]: Started ssh.service - OpenBSD Secure Shell server."]}},"network":{"interfaces":[{"name":"eth0","address":"10.0.0.15/24","up":true,"mac":"52:54:00:3a:1f:02"}],"routes":[{"destination":"default","via":"10.0.0.1","dev":"eth0"}],"hosts":{"10.0.0.1":{"label":"routeur","respondsToPing":true},"10.0.0.2":{"label":"DNS interne","respondsToPing":true,"dns":{"depot.exemple.fr":"10.0.0.80","intranet.exemple.fr":"10.0.0.81","deb.debian.org":"151.101.2.132"}},"10.0.0.80":{"label":"dépôt interne","respondsToPing":true,"http":{"status":200,"body":"<html><body><h1>Index of /paquets</h1></body></html>"}},"1.1.1.1":{"label":"DNS public","respondsToPing":true,"dns":{"deb.debian.org":"151.101.2.132"}},"151.101.2.132":{"label":"miroir Debian","respondsToPing":true,"http":{"status":200,"body":"<html><head><title>Debian -- Mirror</title></head><body>deb.debian.org</body></html>"}}}}},"validators":[{"description":"depot.exemple.fr se résout","check":{"kind":"name_resolves","name":"depot.exemple.fr"}},{"description":"Le dépôt interne répond","check":{"kind":"host_reachable","target":"depot.exemple.fr"}},{"description":"L’ancien serveur DNS n’est plus interrogé","check":{"kind":"file_has_line","path":"/etc/resolv.conf","line":"nameserver 10.0.0.53","expected":false}}],"walkthrough":["curl https://depot.exemple.fr","ping -c 1 10.0.0.1","cat /etc/resolv.conf","dig depot.exemple.fr","cat /root/ticket-1287.txt","dig @10.0.0.2 depot.exemple.fr","echo 'nameserver 10.0.0.2' > /etc/resolv.conf","curl https://depot.exemple.fr"]}}$json$::jsonb),
    ($json${"slug":"reseau-route-par-defaut","title":"Le réseau local répond, Internet non","category":"network","difficulty":"intermediate","ttlMinutes":45,"briefMd":"Après une maintenance faite hier par un collègue, **app03** joint toujours les machines du réseau\nlocal, mais plus rien au-delà : les mises à jour depuis `deb.debian.org` échouent.\n\nRétablissez l'accès à Internet, et faites en sorte que la correction **survive au prochain redémarrage**.\n\n> Machine simulée : tapez `help` pour voir les commandes disponibles.","objectives":["Lire une table de routage avec ip route","Distinguer « Network is unreachable » (pas de route) d’un délai dépassé (pas de réponse)","Corriger à chaud avec ip route, puis rendre la correction persistante"],"hints":[{"text":"Le nom deb.debian.org se résout-il ? Et que dit exactement l’erreur de curl ou de ping vers 1.1.1.1 ?"},{"text":"« Network is unreachable » veut dire « aucune route ». Regardez ip route : où partent les paquets vers Internet ?"},{"text":"La passerelle est dans /etc/network/interfaces. Ajoutez la route à chaud : ip route add default via 10.0.0.1."},{"text":"Pour le prochain démarrage, décommentez la ligne gateway : sed -i 's/#    gateway/    gateway/' /etc/network/interfaces."}],"solutionMd":"**Cause** : la ligne `gateway 10.0.0.1` a été commentée dans `/etc/network/interfaces` pendant la\nmaintenance, puis l'interface a été relancée. La machine n'a plus de **route par défaut** : elle ne sait joindre que\nson propre réseau `10.0.0.0/24`.\n\n**Démarche** : la résolution fonctionne (le DNS interne est sur le réseau local), mais `curl` et `ping 1.1.1.1`\nrépondent « Network is unreachable » : le noyau n'a aucune route. `ip route` ne montre que `10.0.0.0/24`.\n`ip route add default via 10.0.0.1` rétablit l'accès **tout de suite** ; décommenter `gateway` dans\n`/etc/network/interfaces` le rend **durable**.\n\n**À retenir** : « Network is unreachable » (pas de route) n'est pas un délai dépassé (la route existe, la réponse\nne revient pas). Une correction faite avec `ip` disparaît au redémarrage : il faut toujours reporter le changement\ndans la configuration.","simulation":{"machine":{"hostname":"app03","cwd":"/root","clock":"2026-11-24T10:20:00.000Z","nextPid":2100,"dirs":["/etc","/etc/network","/home","/root","/tmp","/usr","/var","/var/log"],"files":{"/etc/hosts":{"size":60,"content":"127.0.0.1\tlocalhost\n127.0.1.1\tapp03\n"},"/var/log/syslog":{"size":4194304,"content":"Nov 24 08:58:02 app03 kernel: Linux version 6.1.0-27-amd64\nNov 24 08:58:05 app03 systemd[1]: Reached target multi-user.target.\nNov 24 08:59:10 app03 CRON[612]: (root) CMD (command -v debian-sa1 > /dev/null && debian-sa1 1 1)\n"},"/etc/resolv.conf":{"size":20,"content":"nameserver 10.0.0.2\n"},"/etc/network/interfaces":{"size":120,"content":"# Interface principale\nauto eth0\niface eth0 inet static\n    address 10.0.0.16/24\n#    gateway 10.0.0.1\n"}},"mounts":[{"target":"/","device":"/dev/sda1","sizeBytes":21474836480,"baseUsedBytes":4402341478}],"services":{"ssh":{"description":"OpenBSD Secure Shell server","active":"active","enabled":true,"process":"sshd","pid":702,"ports":[22],"journal":["nov. 24 08:58:04 app03 systemd[1]: Started ssh.service - OpenBSD Secure Shell server."]}},"network":{"interfaces":[{"name":"eth0","address":"10.0.0.16/24","up":true,"mac":"52:54:00:3a:1f:03"}],"routes":[],"hosts":{"10.0.0.1":{"label":"routeur","respondsToPing":true},"10.0.0.2":{"label":"DNS interne","respondsToPing":true,"dns":{"deb.debian.org":"151.101.2.132","depot.exemple.fr":"10.0.0.80"}},"10.0.0.80":{"label":"dépôt interne","respondsToPing":true,"http":{"status":200,"body":"<html><body><h1>Index of /paquets</h1></body></html>"}},"1.1.1.1":{"label":"DNS public","respondsToPing":true,"dns":{"deb.debian.org":"151.101.2.132"}},"151.101.2.132":{"label":"miroir Debian","respondsToPing":true,"http":{"status":200,"body":"<html><head><title>Debian -- Mirror</title></head><body>deb.debian.org</body></html>"}}}}},"validators":[{"description":"Internet répond (1.1.1.1)","check":{"kind":"host_reachable","target":"1.1.1.1"}},{"description":"deb.debian.org est joignable","check":{"kind":"host_reachable","target":"deb.debian.org"}},{"description":"La passerelle est configurée pour le prochain démarrage","check":{"kind":"file_has_line","path":"/etc/network/interfaces","line":"gateway 10.0.0.1","expected":true}}],"walkthrough":["curl -I http://deb.debian.org","ping -c 1 10.0.0.1","ip route","cat /etc/network/interfaces","ip route add default via 10.0.0.1","sed -i 's/#    gateway/    gateway/' /etc/network/interfaces","ping -c 2 1.1.1.1"]}}$json$::jsonb)
  ) AS v(l)
ON CONFLICT (slug) DO UPDATE
  SET simulation = jsonb_set(labs.lab_templates.simulation, '{walkthrough}', EXCLUDED.simulation->'walkthrough')
  WHERE labs.lab_templates.runtime = 'simulation' AND NOT labs.lab_templates.simulation ? 'walkthrough';
